/**
 * Pro-rate a monthly amount across [from, to) using the real length of each
 * calendar month, so a full calendar month always charges exactly `amount`.
 */
export function prorateMonthly(amount: number, from: Date, to: Date) {
  if (!(from < to) || !amount) return 0;
  return eachMonthOfInterval({ start: startOfMonth(from), end: to }).reduce((sum, m) => {
    const mStart = startOfMonth(m);
    const mEnd = addDays(endOfMonth(mStart), 1);
    const s = dateMax([mStart, from]);
    const e = dateMin([mEnd, to]);
    const days = differenceInDays(e, s);
    if (days <= 0) return sum;
    return sum + (amount * days) / differenceInDays(mEnd, mStart);
  }, 0);
}


