/** Hover text explaining a stay's commission & charges. */
export function chargesNote(p: { estimated: boolean; channelCommission: number; paymentFee: number }) {
  const fmt = (n: number) => n.toLocaleString(undefined, { maximumFractionDigits: 2 });
  const fee = p.paymentFee > 0 ? `bank fee 2.5% (${fmt(p.paymentFee)})` : "";
  if (!(p.channelCommission > 0)) return fee ? fee.charAt(0).toUpperCase() + fee.slice(1) : "";
  const commission = p.estimated
    ? `No commission from the channel; estimated from the channel's % in settings (${fmt(p.channelCommission)})`
    : `Commission charged by the channel (${fmt(p.channelCommission)})`;
  return fee ? `${commission} + ${fee}` : commission;
}

export function stayCommission(booking: Reservation, rates: ChannelCommission[]) {
  const res = withGuestTotal(booking);
  const fee = paymentFee(res);
  // Direct and website bookings pay no channel commission, only the bank fee.
  if (res.source !== "booking" && res.source !== "airbnb") {
    return {
      amount: fee,
      pct: fee > 0 ? BOOKING_PAYMENT_FEE_PCT : 0,
      estimated: false,
      channelCommission: 0,
      paymentFee: fee,
    };
  }
  const total = Number(res.total_price) || 0;
  const actual = Number(res.ota_commission);
  if (res.ota_commission != null && Number.isFinite(actual) && actual > 0) {
    const amount = round2(actual + fee);
    // Without the fee the % is on the commissionable amount, as Booking.com
    // charges it; with the fee it is on the total price the fee is taken from.
    const base = fee > 0 ? total : Number(res.amount_before_tax) || total;
    return {
      amount,
      pct: base > 0 ? Math.round((amount / base) * 1000) / 10 : 0,
      estimated: false,
      channelCommission: actual,
      paymentFee: fee,
    };
  }
  const pct = commissionPct(res.source, rates);
  const estimate = round2(total * (pct / 100));
  return {
    amount: round2(estimate + fee),
    pct: fee > 0 ? round2(pct + BOOKING_PAYMENT_FEE_PCT) : pct,
    estimated: true,
    channelCommission: estimate,
    paymentFee: fee,
  };
}

/**
 * A whole stay's payout: what reaches us. Booking.com and Airbnb bookings are
 * their guest total minus the commission the channel charged (the settings %
 * when a booking has none, flagged as estimated), plus Booking.com's 2.5%
 * payment fee. Direct and website bookings have no channel commission; only
 * the 2.5% bank payment fee comes off.
 */
export function stayPayout(booking: Reservation, rates: ChannelCommission[]) {
  const total = Number(booking.total_price) || 0;
  if (booking.source !== "booking" && booking.source !== "airbnb") {
    const fee = paymentFee(booking);
    return {
      total,
      commission: fee,
      commissionPct: fee > 0 ? BOOKING_PAYMENT_FEE_PCT : 0,
      estimated: false,
      channelCommission: 0,
      paymentFee: fee,
      net: round2(total - fee),
    };
  }
  const guestTotal = Number(withGuestTotal(booking).total_price) || 0;
  const c = stayCommission(booking, rates);
  return {
    total: guestTotal,
    commission: c.amount,
    commissionPct: c.pct,
    estimated: c.estimated,
    channelCommission: c.channelCommission,
    paymentFee: c.paymentFee,
    net: round2(guestTotal - c.amount),
  };
}

